script:
frappe.ui.form.on('Dental Treatment Plan', {
    refresh(frm) {
        frm.add_custom_button('Create Invoice', () => {
            frappe.call({
                method: 'clinify.billing.create_invoice_from_dental_plan',
                args: {
                    plan_name: frm.doc.name
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.msgprint('Invoice created: ' + r.message);
                        frm.reload_doc();
                    }
                }
            });
        });
    }
});

frappe.ui.form.on('Dental Treatment Plan', {
    refresh(frm) {
        frm.fields_dict.dental_planned_procedures.grid.add_custom_button(
            'Mark Completed',
            function () {
                let row = frm.fields_dict.dental_planned_procedures.grid.get_selected_children();
                if (!row || row.length === 0) {
                    frappe.msgprint("Select a procedure row first");
                    return;
                }

                frappe.call({
                    method: "clinify.api.complete_dental_procedure",
                    args: {
                        name: row[0].name
                    },
                    callback: function () {
                        frm.reload_doc();
                    }
                });
            }
        );
    }
});

frappe.ui.form.on("Dental Treatment Plan", {
    refresh(frm) {
        if (frappe.user_roles.includes("Doctor")) {
            frm.toggle_display("clinify_billable_procedures", false);
        } else {
            frm.toggle_display("clinify_billable_procedures", true);
        }
    }
});
